<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id)redirect('/sis-sekolah/siswa/index.php'); $st=$pdo->prepare('SELECT * FROM siswa WHERE id=?');$st->execute([$id]);$existing=$st->fetch();if(!$existing){flash('Data siswa tidak ditemukan.','error');redirect('/sis-sekolah/siswa/index.php');}
$pageTitle='Edit Siswa';$errors=[];$kelas=$pdo->query('SELECT id,nama_kelas FROM kelas ORDER BY nama_kelas')->fetchAll();$data=$existing;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['nis','nama','jenis_kelamin','tanggal_lahir','alamat','no_telepon','id_kelas'] as $k)$data[$k]=trim($_POST[$k]??'');if($data['nis']==='')$errors[]='NIS wajib diisi.';if($data['nama']==='')$errors[]='Nama siswa wajib diisi.';if(!in_array($data['jenis_kelamin'],['Laki-laki','Perempuan'],true))$errors[]='Pilih jenis kelamin yang valid.';if($data['id_kelas']==='')$data['id_kelas']=null;if(!$errors){try{$st=$pdo->prepare('UPDATE siswa SET nis=?,nama=?,jenis_kelamin=?,tanggal_lahir=?,alamat=?,no_telepon=?,id_kelas=? WHERE id=?');$st->execute([$data['nis'],$data['nama'],$data['jenis_kelamin'],$data['tanggal_lahir']?:null,$data['alamat']?:null,$data['no_telepon']?:null,$data['id_kelas'],$id]);flash('Data siswa berhasil diperbarui.');redirect('/sis-sekolah/siswa/index.php');}catch(PDOException $e){$errors[]=$e->getCode()==='23000'?'NIS sudah digunakan atau kelas tidak valid.':'Data gagal diperbarui.';}}}
require __DIR__.'/../includes/header.php'; ?>
<div class="page-heading"><div><span class="eyebrow dark-eyebrow">DATA MANAGEMENT / SISWA</span><h1>Edit siswa</h1><p>Perbarui informasi siswa sesuai data terbaru.</p></div><a class="btn btn-outline" href="index.php">← Kembali</a></div><?php if($errors): ?><div class="alert alert-error"><?php foreach($errors as $err): ?><div><?= e($err) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" class="panel form-panel"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-section-title"><span class="section-number">01</span><div><h2>Informasi pribadi</h2><p>Perbarui identitas dasar siswa.</p></div></div><div class="form-grid"><div class="field"><label for="nis">NIS <span>*</span></label><input class="input" id="nis" name="nis" value="<?= e($data['nis']) ?>" required></div><div class="field"><label for="nama">Nama lengkap <span>*</span></label><input class="input" id="nama" name="nama" value="<?= e($data['nama']) ?>" required></div><div class="field"><label for="jenis_kelamin">Jenis kelamin <span>*</span></label><select class="input" id="jenis_kelamin" name="jenis_kelamin" required><option value="">Pilih jenis kelamin</option><?php foreach(['Laki-laki','Perempuan'] as $jk): ?><option value="<?= e($jk) ?>" <?= $data['jenis_kelamin']===$jk?'selected':'' ?>><?= e($jk) ?></option><?php endforeach; ?></select></div><div class="field"><label for="tanggal_lahir">Tanggal lahir</label><input class="input" type="date" id="tanggal_lahir" name="tanggal_lahir" value="<?= e($data['tanggal_lahir']) ?>"></div><div class="field"><label for="no_telepon">Nomor telepon</label><input class="input" id="no_telepon" name="no_telepon" value="<?= e($data['no_telepon']) ?>"></div><div class="field"><label for="id_kelas">Kelas</label><select class="input" id="id_kelas" name="id_kelas"><option value="">Pilih kelas (opsional)</option><?php foreach($kelas as $k): ?><option value="<?= (int)$k['id'] ?>" <?= (string)$data['id_kelas']===(string)$k['id']?'selected':'' ?>><?= e($k['nama_kelas']) ?></option><?php endforeach; ?></select></div><div class="field field-full"><label for="alamat">Alamat</label><textarea class="input" id="alamat" name="alamat" rows="3"><?= e($data['alamat']) ?></textarea></div></div><div class="form-actions"><span class="required-note"><span>*</span> Wajib diisi</span><div><a class="btn btn-outline" href="index.php">Batal</a> <button class="btn btn-primary" type="submit">Simpan perubahan <span>→</span></button></div></div></form><?php require __DIR__.'/../includes/footer.php'; ?>
